# Cloakroom hook launcher for PowerShell (Windows without Git Bash): hook.ps1 start|prompt|pre|post, hook JSON on
# stdin. Runs the cloakroom program if it is installed; otherwise answers for it and starts the installer.
# Generated by scripts/gen_hooks.py in the cloakroom repository; edit that file, not this one.
param([string]$E)
# UTF-8 without a byte-order mark: Windows PowerShell 5.1's [Text.Encoding]::UTF8 adds one to piped input
$u = New-Object System.Text.UTF8Encoding $false; [Console]::InputEncoding = $u; [Console]::OutputEncoding = $u; $OutputEncoding = $u
switch ($E) {
  'start' { $inst = '{"systemMessage": "cloakroom: installing itself (one time). Rules-only protection starts in about a minute, the full model follows in a few minutes. Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin."}'
    $noinst = '{"systemMessage": "cloakroom: not installed, and nothing to install it with (uv, pipx or Python 3.10+). Install uv: https://docs.astral.sh/uv/getting-started/installation/, then restart Claude Code and Cloakroom installs itself. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}'
    $failed = '{"systemMessage": "cloakroom: the automatic install failed (details: ~/.cloakroom/bootstrap.log); it tries again in 10 minutes. On Ubuntu/Debian it usually needs: sudo apt install python3-venv. Or install it yourself, see https://github.com/shanjeevrajendran/cloakroom#get-started for the command. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}' }
  'prompt' { $inst = '{"systemMessage": "cloakroom: installing itself (one time). Rules-only protection starts in about a minute, the full model follows in a few minutes. Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin.", "hookSpecificOutput": {"hookEventName": "UserPromptSubmit", "additionalContext": "The Cloakroom privacy plugin is enabled but its program is not installed yet, so every tool call is denied until it is. Tell the user what the Cloakroom message says if they ask why tools are blocked."}}'
    $noinst = '{"systemMessage": "cloakroom: not installed, and nothing to install it with (uv, pipx or Python 3.10+). Install uv: https://docs.astral.sh/uv/getting-started/installation/, then restart Claude Code and Cloakroom installs itself. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.", "hookSpecificOutput": {"hookEventName": "UserPromptSubmit", "additionalContext": "The Cloakroom privacy plugin is enabled but its program is not installed yet, so every tool call is denied until it is. Tell the user what the Cloakroom message says if they ask why tools are blocked."}}'
    $failed = '{"systemMessage": "cloakroom: the automatic install failed (details: ~/.cloakroom/bootstrap.log); it tries again in 10 minutes. On Ubuntu/Debian it usually needs: sudo apt install python3-venv. Or install it yourself, see https://github.com/shanjeevrajendran/cloakroom#get-started for the command. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.", "hookSpecificOutput": {"hookEventName": "UserPromptSubmit", "additionalContext": "The Cloakroom privacy plugin is enabled but its program is not installed yet, so every tool call is denied until it is. Tell the user what the Cloakroom message says if they ask why tools are blocked."}}' }
  'pre' { $inst = '{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "Cloakroom blocked this tool call: installing itself (one time). Rules-only protection starts in about a minute, the full model follows in a few minutes. Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin."}}'
    $noinst = '{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "Cloakroom blocked this tool call: not installed, and nothing to install it with (uv, pipx or Python 3.10+). Install uv: https://docs.astral.sh/uv/getting-started/installation/, then restart Claude Code and Cloakroom installs itself. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}}'
    $failed = '{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "Cloakroom blocked this tool call: the automatic install failed (details: ~/.cloakroom/bootstrap.log); it tries again in 10 minutes. On Ubuntu/Debian it usually needs: sudo apt install python3-venv. Or install it yourself, see https://github.com/shanjeevrajendran/cloakroom#get-started for the command. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}}' }
  'post' { $inst = '{"hookSpecificOutput": {"hookEventName": "PostToolUse", "updatedToolOutput": "[Cloakroom blocked this tool call: installing itself (one time). Rules-only protection starts in about a minute, the full model follows in a few minutes. Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin.]"}}'
    $noinst = '{"hookSpecificOutput": {"hookEventName": "PostToolUse", "updatedToolOutput": "[Cloakroom blocked this tool call: not installed, and nothing to install it with (uv, pipx or Python 3.10+). Install uv: https://docs.astral.sh/uv/getting-started/installation/, then restart Claude Code and Cloakroom installs itself. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.]"}}'
    $failed = '{"hookSpecificOutput": {"hookEventName": "PostToolUse", "updatedToolOutput": "[Cloakroom blocked this tool call: the automatic install failed (details: ~/.cloakroom/bootstrap.log); it tries again in 10 minutes. On Ubuntu/Debian it usually needs: sudo apt install python3-venv. Or install it yourself, see https://github.com/shanjeevrajendran/cloakroom#get-started for the command. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.]"}}' }
  default { [Console]::Error.WriteLine('usage: hook.ps1 start|prompt|pre|post'); exit 2 }
}
$h = if ($env:CLOAKROOM_HOME) { $env:CLOAKROOM_HOME } else { Join-Path $env:USERPROFILE '.cloakroom' }
# the program: on PATH, in ~/.local/bin (where the installers put it) or in ~/.cloakroom/venv
$cr = (Get-Command cloakroom -ErrorAction SilentlyContinue).Source
foreach ($c in @((Join-Path $env:USERPROFILE '.local\bin\cloakroom.exe'), (Join-Path $h 'venv\Scripts\cloakroom.exe'))) {
  if (-not $cr -and (Test-Path $c)) { $cr = $c }
}
# a failed install retries after 10 minutes, not on every call
$st = Join-Path $h 'bootstrap.state'
$recent = (Test-Path $st) -and ((Get-Content $st -ErrorAction SilentlyContinue) -eq 'failed') -and
  (((Get-Date) - (Get-Item $st).LastWriteTime).TotalMinutes -lt 10)
$boot = Join-Path $env:CLAUDE_PLUGIN_ROOT 'scripts\bootstrap.ps1'
if ($cr) { [Console]::In.ReadToEnd() | & $cr hook $E }
elseif ($recent) { $failed }
else {
  & $boot -Check
  if ($LASTEXITCODE -eq 0) {
    Start-Process (Get-Process -Id $PID).Path -WindowStyle Hidden -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-File',('"' + $boot + '"') | Out-Null
    $inst
  }
  else { $noinst }
}
exit 0
